<?php declare(strict_types=1); ?><!doctype html><html lang="<?= e(\App\Core\Translator::locale()) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e(villa_ui('Sayfa düzenle')) ?></title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:850px;margin:35px auto;padding:0 18px}.panel{background:white;padding:24px;border-radius:14px}label{display:block;margin:15px 0;font-weight:700;font-size:13px}input,textarea,select{display:block;width:100%;box-sizing:border-box;padding:12px;border:1px solid #dfe6e0;border-radius:8px;margin-top:6px;font:inherit}textarea{min-height:300px}.btn{background:#176b50;color:white;border:0;padding:13px 18px;border-radius:8px;font-weight:700}
/* Consistent admin links and actions */
a{color:#176b50;text-decoration:none;transition:color .18s ease,background-color .18s ease,border-color .18s ease}a:hover{color:#104c39;text-decoration:none}td a:not([class]),.table-wrap a:not([class]){display:inline-flex;align-items:center;justify-content:center;padding:7px 11px;border:1px solid #dce9e0;border-radius:8px;background:#f5faf6;color:#176b50;font-size:12px;font-weight:750;white-space:nowrap}td a:not([class]):hover,.table-wrap a:not([class]):hover{background:#eaf4ee;border-color:#b9d8c4}button,input[type=submit]{cursor:pointer;font:inherit}button{transition:filter .18s ease,transform .18s ease}button:hover,input[type=submit]:hover{filter:brightness(.96)}
