aşlığı')) ?><input name="title" required maxlength="220" value="<?= e($page['title']??'') ?>"></label><label><?= e(villa_ui('URL kısa adı')) ?><input name="slug" required maxlength="240" value="<?= e($page['slug']??'') ?>"></label><label><?= e(villa_ui('Yayın durumu')) ?><select name="status"><option value="draft" <?= ($page['status']??'draft')==='draft'?'selected':'' ?>><?= e(villa_ui('Taslak')) ?></option><option value="published" <?= ($page['status']??'')==='published'?'selected':'' ?>><?= e(villa_ui('Yayında')) ?></option></select></label><label><?= e(villa_ui('SEO başlığı')) ?><input name="meta_title" maxlength="220" value="<?= e($page['meta_title']??'') ?>"></label><label><?= e(villa_ui('SEO açıklaması')) ?><input name="meta_description" maxlength="320" value="<?= e($page['meta_description']??'') ?>"></label><label><?= e(villa_ui('Odak anahtar kelime')) ?><input name="focus_keyword" maxlength="120" value="<?= e($page['focus_keyword']??'') ?>" placeholder="Örn. Kaş kiralık villa"></label><label><?= e(villa_ui('İsteğe bağlı düz metin içeriği (görsel editör kullanılmıyorsa)')) ?><textarea name="content"><?= e($page['content']??'') ?></textarea></label><?php include dirname(__DIR__,2) . '/partials/seo-analyzer.php'; ?><button class="btn"><?= e(villa_ui('Kaydet')) ?></button></section></form><p><a href="/admin/pages?lang=<?= e(rawurlencode($locale)) ?>"><?= e(villa_ui('Sayfalara dön')) ?></a></p></main></body></html>